cat > $CLAUDE_JOB_DIR/tmp/cmpwav.py <<'EOF'
import sys, wave, struct
def rd(p):
    w = wave.open(p); n = w.getnframes(); ch = w.getnchannels(); r = w.getframerate()
    d = struct.unpack("<%dh" % (n*ch), w.readframes(n)); return d, ch, r
a, ch, r = rd(sys.argv[1]); b, _, _ = rd(sys.argv[2])
print("frames", len(a)//ch, len(b)//ch, "ch", ch, "rate", r)
def first_nz(x):
    for i,v in enumerate(x):
        if v: return i//ch
print("first nonzero frame", first_nz(a), first_nz(b))
# find shift s so b[i] == a[i+s]
for s in range(-300, 301):
    sa = s*ch
    lo = max(0, -sa); hi = min(len(b), len(a)-sa)
    if hi - lo > 0 and all(b[i] == a[i+sa] for i in range(lo, hi)):
        print("b == a shifted by", s, "frames, over", (hi-lo)//ch); break
else:
    # first differing frame at shift 0
    for i in range(min(len(a),len(b))):
        if a[i]!=b[i]: print("first diff frame", i//ch); break
EOF
